        //             "marketId": 2107,
        //             "marketQuestion": "Will Trump acquire Greenland before 2027?",
        //             "outcome": "YES",
        //             "outcomeIndex": 1,
        //             "outcomeName": "Yes",
        //             "price": "0.010",
        //             "quantity": "1.000",
        //             "quantityFilled": "1.000",
        //             "quoteType": "ASK",
